import java.util.Arrays;

class BubbleSort {
    private static final int[] TEST_DATA = {64, 34, 25, 12, 22, 11, 90};

    void sort(int[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            if (!performPass(arr, i)) break;
        }
    }

    private boolean performPass(int[] arr, int passIndex) {
        boolean swapped = false;
        for (int j = 0; j < arr.length - passIndex - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(arr, j, j + 1);
                swapped = true;
            }
        }
        return swapped;
    }

    private void swap(int[] arr, int i, int j) {
        arr[i] = arr[i] ^ arr[j];
        arr[j] = arr[i] ^ arr[j];
        arr[i] = arr[i] ^ arr[j];
    }

    public static void main(String[] args) {
        BubbleSort sorter = new BubbleSort();
        int[] arr = TEST_DATA.clone();
        sorter.sort(arr);
        System.out.println("Sorted array: " + Arrays.toString(arr));
    }
}

